hudson.tasks.Shell.command:
#!/bin/bash -e
export APP_LOG_PATH=${APP_LOG_PATH}
export SPRING_PROFILES_ACTIVE=${SPRING_PROFILES_ACTIVE}
# Start a MySQL 9 container for the job (ephemeral)
docker run --name jenkins-erp-mysql -e MYSQL_ROOT_PASSWORD=root -e MYSQL_DATABASE=erp_database -d -p 3307:3306 mysql:9.0
# Wait for readiness
for i in {1..60}; do docker exec jenkins-erp-mysql mysqladmin ping -uroot -proot --silent && break || sleep 2; done
# Run tests
./mvnw -B -DskipTests=false test || rc=$?
RC=${rc:-0}
# Tear down DB
docker rm -f jenkins-erp-mysql || true
exit $RC
